import * as E from './engine.js';
import {createWorld} from './scene.js';
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const paths={coin:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="5"/><path d="M12 7v10m-3-7h4a2 2 0 010 4H9"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 015.8 1c0 2-2.8 2-2.8 4m0 3v.1"/>',settings:'<path d="m9 3-1 3-3 1 1 3-2 2 2 2-1 3 3 1 1 3h5l1-3 3-1-1-3 2-2-2-2 1-3-3-1-1-3z"/><circle cx="11.5" cy="12" r="3"/>',palm:'<path d="M11 21c2-6 2-9 1-14m0 1C5 9 3 5 2 4c5-2 8 0 10 4zm0 0c2-5 5-6 9-4-1 3-4 5-9 4zm0 0C9 2 7 1 5 2m7 6c6-1 9 2 10 5-5 0-8-2-10-5zm0 0c-6 0-8 3-9 6 5-1 7-3 9-6zM7 21h10"/>',shield:'<path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6z"/><path d="m8 12 3 3 5-6"/>',water:'<path d="M12 2S5 10 5 15a7 7 0 0014 0c0-5-7-13-7-13zM8 15c0 2 1 3 3 3"/>',food:'<path d="M4 20 19 5M7 17c-4-1-4-5-3-7 3 0 5 2 5 5m1-3c-3-2-3-5-2-7 3 1 4 3 4 5m1-2c-1-3 0-5 2-6 2 2 2 4 1 6m-3 5c2 1 5 0 7-2-2-2-5-2-7 0m-4 6c3 1 6-1 7-3-3-1-5-1-7 1"/>',heart:'<path d="M20 5c-3-3-7-1-8 2-1-3-5-5-8-2-5 5 1 10 8 16 7-6 13-11 8-16z"/>',camp:'<path d="m2 20 10-17 10 17H2zm6 0 4-8 4 8M8 2l8 3"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 10v7m0-11v1"/>',plus:'<path d="M12 4v16M4 12h16"/>',camel:'<path d="M3 21V11l3-2 3 2 3-3 3 3h3V7l-1-3 3-1 2 3-2 2v8h-3l-1 5m-8-7-1 7m-4-6h13M2 11 1 8"/>',arrow:'<path d="M4 12h15m-5-5 5 5-5 5"/>',route:'<circle cx="5" cy="5" r="2"/><circle cx="19" cy="19" r="2"/><path d="M7 5h9a4 4 0 010 8H8a3 3 0 000 6h9"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',moon:'<path d="M20 15A9 9 0 019 3a9 9 0 1011 12z"/>',focus:'<path d="M4 9V4h5m6 0h5v5m0 6v5h-5m-6 0H4v-5"/><circle cx="12" cy="12" r="3"/>',mouse:'<rect x="6" y="2" width="12" height="20" rx="6"/><path d="M12 2v7M6 9h12"/>',pause:'<path d="M8 5v14M16 5v14"/>',play:'<path d="m7 4 13 8-13 8z"/>',sparkles:'<path d="m13 2 2 6 6 2-6 2-2 6-2-6-6-2 6-2zM5 15l1 3 3 1-3 1-1 3-1-3-3-1 3-1z"/>',book:'<path d="M12 5C9 2 4 3 2 4v15c3-1 7-1 10 2 3-3 7-3 10-2V4c-2-1-7-2-10 1zm0 0v16"/>',chevron:'<path d="m9 5 7 7-7 7"/>',volume:'<path d="m3 9 5 0 5-5v16l-5-5H3zM17 9c2 2 2 4 0 6m3-10c4 4 4 10 0 14"/>',mute:'<path d="m3 9 5 0 5-5v16l-5-5H3zM17 9l5 6m0-6-5 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5z"/>',salt:'<path d="m3 18 4-9 3 3 4-8 7 14H3zM7 9l3 9m4-14 1 14M6 21h13"/>',dates:'<path d="M13 4c2-2 4-2 6-1m-7 2 4 4M6 8c-5 6-1 12 3 8s4-10 1-10L6 8zm8 2c-4 5-1 12 3 8s5-9 2-10l-5 2z"/>',copper:'<path d="M5 8h14l-2 12H7L5 8zm2-1V5h10v2M3 10H1v5h5m13-5h4v5h-5M9 3h6M8 12h8"/>',silk:'<path d="M5 5c4-4 11-1 14 0v15c-4-4-10 0-14-3V5zM5 5c3 3 10 0 14 0M8 9c3 1 5-1 8 0m-8 4c3 1 5-1 8 0"/>',spice:'<path d="m7 3 5 2 5-2-2 5c6 6 8 13-3 13S3 14 9 8L7 3zm2 5h6M8 15h8m-6-3v6m4-6v6"/>',gems:'<path d="m3 8 4-5h10l4 5-9 13L3 8zm0 0h18M7 3l5 18 5-18M8 8l4-5 4 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',trend:'<path d="m3 17 6-6 4 3 8-10m-6 0h6v6"/>',flag:'<path d="M5 22V3m0 1c5-5 9 5 15 0v10c-6 5-10-5-15 0"/>',box:'<path d="m3 7 9-5 9 5v11l-9 4-9-4V7zm0 0 9 5 9-5M12 12v10M8 4l9 5"/>',wind:'<path d="M2 8h14a3 3 0 10-3-3M2 12h18a3 3 0 11-3 3M2 17h7a2 2 0 11-2 2"/>'};
function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.box}</svg>`;}function fillIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}fillIcons();
const KEY='sands-and-silk-save-v1';let s;try{const data=JSON.parse(localStorage.getItem(KEY));s=data?.version===1?{...E.freshState(),...data}:E.freshState();}catch{s=E.freshState();}let selected=s.route[0]||'salt',tab='market',modalView='',lastFocus=null;let world;let lastFrame=performance.now(),saveTimer=0,night=false,audioCtx=null,audioGain=null;
function toast(message,type=''){const n=document.createElement('div');n.className='toast '+type;n.textContent=message;$('#toasts').append(n);setTimeout(()=>n.remove(),3700);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(s));$('#save-state').textContent='旅程已自动保存';}catch{$('#save-state').textContent='浏览器未允许保存';}}
function act(fn,success){const err=fn();if(err){toast(err,'error');return;}E.checkAchievements(s).forEach(n=>toast('✦ 达成成就：'+n,'good'));if(success)toast(success,'good');save();render();if(modalView&&!['event','help','settings','reset'].includes(modalView))openModal(modalView,false);}
const fmt=n=>Math.round(n).toLocaleString('zh-CN');function qty(){return Math.max(1,Math.min(99,parseInt($('#trade-qty').value)||1));}
function render(){const loc=E.cityBy(s.location),c=E.cityBy(selected);$('#coins').textContent=fmt(s.coins);$('#location-name').textContent=loc.name;$('#location-desc').textContent=loc.desc;$('#city-type').textContent=loc.type;$('#cargo-badge').textContent=E.cargoCount(s);$('#day').textContent=`第 ${s.day} 天`;$('#weather').textContent=s.weather;$('#season').textContent=s.day<16?'流沙纪 · 初夏':s.day<32?'流沙纪 · 盛夏':'流沙纪 · 季风';$('#rank').textContent=s.rep>=45?'沙海传奇':s.rep>=25?'商路名家':s.rep>=10?'远行商人':'初出茅庐';$('#level').textContent=String(1+Math.floor(s.rep/10)).padStart(2,'0');$('#caravan-summary').textContent=`${3+s.upgrades.camels} 匹骆驼 · 货舱 ${E.cargoCount(s)}/${E.capacity(s)}`;$('#caravan-status').textContent=s.trip?(s.paused?'已暂停':'行进中'):'驻扎中';$('#log-count').textContent=String(s.log.length).padStart(2,'0');$('#goal-progress').style.width=s.visits.length/6*100+'%';$('#goal-text').textContent=`探索 ${s.visits.length} / 6 座城镇`;$('#pause').innerHTML=icon(s.paused?'play':'pause');$('#pause').title=s.paused?'继续旅程':'暂停旅程';$('#audio i').innerHTML=icon(s.muted?'mute':'volume');$$('[data-speed]').forEach(el=>el.classList.toggle('active',+el.dataset.speed===s.speed));
const goods=tab==='market'?E.GOODS:E.GOODS.filter(g=>(s.cargo[g.id]||0)>0);$('#market-content').innerHTML=`<div class="market-header"><span>${tab==='market'?'货物 / 供需':'货物 / 持有'}</span><span>${tab==='market'?'买入价':'卖出价'}</span><span>${tab==='market'?'购入':'卖出'}</span></div>`+(goods.length?goods.map(g=>{const special=loc.special===g.id,demand=loc.demand===g.id,p=tab==='market'?E.quote(s,s.location,g.id):E.sellQuote(s,s.location,g.id);return `<div class="good-row"><div class="good-main"><span class="good-icon" style="--good-color:${g.color};--good-bg:${g.color}18">${icon(g.icon)}</span><div class="good-name">${g.name}<small>${tab==='market'?(special?'本地特产':demand?'市场紧缺':g.en):`${s.cargo[g.id]} 箱 · ${fmt(p*s.cargo[g.id])} 金`}</small></div></div><div class="good-price">${p}<small class="${demand?'high':''}">${tab==='market'?(special?'↓ 供给充足':demand?'↑ 需求旺盛':`余 ${E.stock(s,s.location,g.id)} 箱`):(demand?'↑ 适合卖出':'金币 / 箱')}</small></div><button class="buy-btn ${tab==='cargo'?'sell-btn':''}" data-trade="${g.id}" ${s.trip?'disabled':''}>${tab==='market'?'买入 +':'卖出 −'}</button></div>`;}).join(''):'<div class="empty-cargo">货舱空空如也。<br>到当地市场购入特产，<br>开启下一场贸易。</div>');
$('#supplies').innerHTML=[['water','饮水',s.water,80,'water'],['food','口粮',s.food,60,'food'],['morale','士气',s.morale,100,'heart']].map(([kind,name,val,max,ic])=>`<div class="supply-row ${kind}"><i>${icon(ic)}</i><span class="supply-name">${name}</span><span class="supply-track"><span style="width:${val/max*100}%;${val/max<.25?'background:#b16b4d':''}"></span></span><span class="supply-value">${val}<span style="opacity:.5"> / ${max}</span></span>${kind!=='morale'?`<button data-supply="${kind}" title="购买 10 份${name}" aria-label="购买 10 份${name}" ${s.trip?'disabled':''}>+</button>`:'<span style="width:13px"></span>'}</div>`).join('');
const activeTrip=!!s.trip;$('#rest').disabled=activeTrip;$('#resupply').disabled=activeTrip;$('#merchant-tip').textContent=s.coins<30?'周转困难时，可在「我的商队」向商会领取应急补给。':'北方的白盐古城正需要椰枣。沿着驼铃声，做成你的第一笔生意。';const special=E.goodBy(c.special),demand=E.goodBy(c.demand);const lastStop=s.route.at(-1)||s.trip?.to||s.location;const queued=s.route.includes(c.id);$('#selected-city').innerHTML=`<div class="destination-card"><div class="destination-card-top"><div><h3>${c.name}</h3><span class="en">${c.en}</span></div><span class="dest-symbol">${icon(c.id==='dawn'?'palm':c.id==='gems'?'gems':c.id==='salt'?'salt':'camp')}</span></div><p>${c.desc}</p><div class="demand-line"><span>盛产</span><strong>${special.name} · ${E.quote(s,c.id,special.id)} 金</strong></div><div class="demand-line"><span>收购</span><strong class="demand">${demand.name} · ${E.sellQuote(s,c.id,demand.id)} 金</strong></div><button class="add-route" id="add-route" ${c.id===lastStop?'disabled':''}>${icon('plus')} ${c.id===lastStop?'已在当前站点':queued?'再次加入行程':'加入我的行程'}</button></div>`;
$('#route-count').textContent=s.route.length?`${s.route.length} 站`:'';let from=s.trip?.to||s.location;$('#route-list').innerHTML=`<div class="route-stop"><span class="stop-dot">●</span><span>${E.cityBy(from).name}</span><small>${s.trip?'即将抵达':'出发地'}</small></div>`+s.route.map((id,i)=>{const info=E.legInfo(s,from,id);from=id;return `<div class="route-stop"><span class="stop-dot">${i+1}</span><span>${E.cityBy(id).name}</span><small>${info.days} 天</small><button data-remove-stop="${i}" aria-label="移除${E.cityBy(id).name}">×</button></div>`;}).join('')+(!s.route.length?'<div class="empty-route">点击地图上的城镇，<br>将目的地加入你的行程。</div>':'');const info=E.routeInfo({...s,location:s.trip?.to||s.location});$('#route-summary').innerHTML=s.route.length?`<div class="route-metrics"><div><small>预计耗时</small><strong>${info.days} 天</strong></div><div><small>所需补给</small><strong><i>${icon('water')}</i>${info.water} <i>${icon('food')}</i>${info.food}</strong></div><div><small>旅途风险</small><strong class="${info.risk>30?'danger':''}">${info.risk>30?'较高':info.risk>16?'适中':'较低'}</strong></div></div>`:'';$('#depart').disabled=activeTrip||!s.route.length;$('#depart span').textContent=activeTrip?'商队行进中':s.route.length>1?'启程，探索商路':'启程，踏上商路';$('#departure-note').textContent=activeTrip?'抵达后可交易，再继续下一段旅程':s.route.length?(s.water>=info.water&&s.food>=info.food?'补给充足 · 愿旅途一路平安':'补给不足以完成全部行程，请沿途补充'):'先选择地图上的一座城镇';
const rumorCity=E.CITIES[Math.floor(s.day/4)%6];$('#rumors').innerHTML=`<div class="rumor"><i>${icon('trend')}</i><div><strong>${rumorCity.name}的商机</strong><p>当地急需<b>${E.goodBy(rumorCity.demand).name}</b>，当前收购价为 <b>${E.sellQuote(s,rumorCity.id,rumorCity.demand)} 金币</b>。</p><small>商会信使 · 今日</small></div></div><div class="rumor"><i>${icon(s.weather==='沙尘'?'wind':'sun')}</i><div><strong>${s.weather==='沙尘'?'风沙正在靠近':'适合远行的日子'}</strong><p>${s.weather==='沙尘'?'为下一程准备充足的水与口粮。护卫与向导能让旅途更从容。':'沿绿洲间的商路行进，记得在出发前补充饮水。'}</p><small>驿站守望人 · 第 ${s.day} 天</small></div></div>`;world?.update(s,selected);renderJourney();if(s.event&&modalView!=='event')openModal('event');}
function renderJourney(){const el=$('#journey-banner');el.classList.toggle('hidden',!s.trip);if(s.trip){el.innerHTML=`<strong><span>${E.cityBy(s.trip.from).name} → ${E.cityBy(s.trip.to).name}</span><span>${Math.min(100,Math.floor(s.trip.progress*100))}%</span></strong><div class="journey-track"><span style="width:${Math.min(100,s.trip.progress*100)}%"></span></div><small>${s.event?'遇到了新情况，等待你的决定':s.paused?'商队已暂停 · 点击播放继续':`驼铃悠扬 · 预计 ${s.trip.info.days} 天抵达`}</small>`;}}
function selectCity(id){selected=id;render();}try{world=createWorld($('#world'),selectCity);}catch(error){console.error(error);$('#world').innerHTML='<div class="webgl-fallback"><h3>开启沙海之旅</h3><p>3D 地图需要浏览器启用硬件加速。<br>你仍可从下方选择城镇，进行交易和旅行。</p><div>'+E.CITIES.map(c=>`<button class="primary-small" data-select-city="${c.id}" style="margin:5px">${c.name}</button>`).join('')+'</div></div>';}
function openModal(view,focus=true){if(s.event&&view!=='event')return;modalView=view;if(focus)lastFocus=document.activeElement;$('#modal-backdrop').classList.remove('hidden');$('#modal-close').classList.toggle('hidden',view==='event');const node=$('#modal-content');let html='';if(view==='caravan'){const unlocked=s.achievements;html=`<span class="modal-eyebrow">THE WINDWALKERS</span><h2 id="modal-title">风行者商队</h2><p class="modal-intro">驼铃相伴，行商为生。让每一次抵达，都成为下一次远行的底气。</p><div class="modal-stats"><div class="modal-stat"><span>商队总资产</span><strong>${fmt(E.netWorth(s))} <small>金</small></strong></div><div class="modal-stat"><span>货舱容量</span><strong>${E.cargoCount(s)} / ${E.capacity(s)}</strong></div><div class="modal-stat"><span>商会声望</span><strong>${s.rep}</strong></div><div class="modal-stat"><span>已完成旅程</span><strong>${s.legs}</strong></div></div><div class="modal-grid">${E.UPGRADES.map(u=>`<div class="upgrade-card"><i>${icon(u.icon)}</i><h3>${u.name}</h3><p>${u.desc}</p><div class="upgrade-footer"><small>等级 ${s.upgrades[u.id]} / ${u.max}</small><button class="primary-small" data-upgrade="${u.id}" ${s.trip||s.upgrades[u.id]>=u.max?'disabled':''}>${s.upgrades[u.id]>=u.max?'已升满':`${u.base*(s.upgrades[u.id]+1)} 金币 · 升级`}</button></div></div>`).join('')}</div><div class="achievement-list">${[['first','第一次远行'],['trader','熟练行商'],['explorer','沙海足迹'],['rich','富甲一方'],['guild','商会之友']].map(([id,n])=>`<span class="${unlocked.includes(id)?'unlocked':''}">✦ ${n}</span>`).join('')}</div>${s.coins<30?'<div class="setting-row"><div>商会应急援助<small>领取免费的基本水粮；空货舱可获得 5 箱椰枣。</small></div><button class="secondary-small" id="rescue">领取救济</button></div>':''}`;}
if(view==='contracts'){html=`<span class="modal-eyebrow">THE MERCHANTS GUILD</span><h2 id="modal-title">商会委托</h2><p class="modal-intro">替远方的人带去所需之物，换取丰厚报酬与商会声望。同时最多接受 3 项委托。</p><div class="modal-grid">${E.CONTRACTS.map(c=>{const active=s.contracts.find(t=>t.id===c.id),done=s.completed.includes(c.id);return `<div class="contract-card"><div class="contract-top"><h3>${c.name}</h3><span>${done?'✓ 已完成':active?'进行中':'可接受'}</span></div><p>${c.desc}</p><div class="contract-goods">${E.goodBy(c.good).name} × ${c.qty} 箱 · ${E.cityBy(c.city).name}</div><div class="contract-reward">奖励 ${fmt(c.reward)} 金币 · 声望 +${c.rep}</div><button class="${active?'primary-small':'secondary-small'}" data-contract="${c.id}" data-contract-action="${active?'deliver':'accept'}" ${done?'disabled':''}>${done?'委托已完成':active?'交付货物':'接受委托'}</button><div class="contract-meta">${done?'商会感谢你的可靠与守信':active?`截止第 ${active.deadline} 天 · 还剩 ${active.deadline-s.day} 天`:`接受后 ${c.days} 天内交付`}</div></div>`;}).join('')}</div>`;}
if(view==='journal'){html=`<span class="modal-eyebrow">A MERCHANT'S JOURNAL</span><h2 id="modal-title">沙海中的足迹</h2><p class="modal-intro">每一次交易，每一段旅程，都在这里留下故事。</p>${s.log.map(l=>`<div class="journal-entry ${l.type}"><time>第 ${l.day} 天</time><p>${l.text}</p></div>`).join('')}`;}
if(view==='help'){html=`<span class="modal-eyebrow">WELCOME TO THE SAND SEA</span><h2 id="modal-title">一袋货物，一条商路</h2><p class="modal-intro">你是风行者商队的领队。从曙光绿洲出发，在六座城镇之间经营贸易，积累财富与声望。</p><ol class="help-list"><li><div><b>在产地买入，在需求地卖出。</b><br>绿色标记代表本地特产。买卖会改变供需；每次出行后，物价也会浮动。</div></li><li><div><b>点击城镇，把远方加入行程。</b><br>可规划最多 5 站。每次启程走一段，抵达后交易、补给，再出发。</div></li><li><div><b>水、口粮与士气，是沙漠中的财富。</b><br>补给在出发时扣除。驿站休整可恢复士气；商队升级能扩大货舱、降低风险与消耗。</div></li><li><div><b>完成委托，写下你的商旅传奇。</b><br>探索全部 6 座城镇、积累 10,000 金币资产，成为富甲一方的商人。成就会自动发放奖励。</div></li></ol><div class="help-card"><h3>推荐的第一笔生意</h3><p>在曙光绿洲买入椰枣 → 前往白盐古城 → 切到「商队货舱」卖出。也可以先接受「北方的甜蜜」委托，携带 12 箱椰枣交付。</p><button class="primary-small" id="tutorial-route">规划这条商路</button></div><p class="modal-intro" style="margin:20px 0 0">拖拽旋转 · 滚轮缩放 · 空格暂停 · M 商队 · C 委托 · J 日志<br>进度自动保存在当前浏览器。旅途中关闭后，也能从原处继续。</p>`;}
if(view==='settings'){html=`<span class="modal-eyebrow">SETTINGS</span><h2 id="modal-title">旅途偏好</h2><div class="setting-row"><div>沙海之声<small>轻柔风声与商队驼铃</small></div><button class="secondary-small" id="toggle-audio">${s.muted?'开启声音':'关闭声音'}</button></div><div class="setting-row"><div>昼夜景色<small>切换日光沙海与月色沙海</small></div><button class="secondary-small" id="toggle-night">${night?'切换白昼':'切换夜晚'}</button></div><div class="setting-row"><div>自动存档<small>当前第 ${s.day} 天 · 资产 ${fmt(E.netWorth(s))} 金币<br>进度仅保存在当前设备与浏览器。</small></div><button class="secondary-small" id="manual-save">立即保存</button></div><div class="setting-row"><div>重新启程<small>清除当前进度，从曙光绿洲开始新的旅程。</small></div><button class="danger-btn" id="reset-game">重新开始</button></div>`;}
if(view==='reset'){html='<span class="modal-eyebrow">A NEW JOURNEY</span><h2 id="modal-title">重新踏上商路？</h2><p class="modal-intro">当前金币、货物、委托与旅程记录将被清除。这次操作无法撤销。</p><div style="display:flex;gap:12px"><button class="primary-small" id="confirm-reset">确认重新开始</button><button class="secondary-small" id="cancel-reset">保留我的旅程</button></div>';}
if(view==='event'&&s.event){const e=s.event;html=`<div class="event-art"><i>${icon(e.id==='storm'?'wind':e.id==='ruins'?'gems':e.id==='traveler'?'compass':'camel')}</i></div><span class="modal-eyebrow">${e.tag} · CARAVAN ENCOUNTER</span><h2 id="modal-title">${e.title}</h2><p class="modal-intro">${e.text}</p><div class="event-choices">${e.choices.map(c=>`<button class="event-choice" data-choice="${c.kind}"><strong>${c.label}</strong><small>${c.detail}</small></button>`).join('')}</div>`;}
node.innerHTML=html;if(focus){requestAnimationFrame(()=>{const first=$('#modal').querySelector('button:not(.hidden):not(:disabled)');first?.focus();});}$$('.nav-text').forEach(el=>el.classList.toggle('active',el.dataset.view===view));}
function closeModal(){if(s.event)return;$('#modal-backdrop').classList.add('hidden');modalView='';$$('.nav-text').forEach(el=>el.classList.toggle('active',el.dataset.view==='map'));lastFocus?.focus();}
function addRoute(){const from=s.route.at(-1)||s.trip?.to||s.location;if(from===selected)return;if(s.route.length>=5){toast('一次最多规划 5 站','error');return;}s.route.push(selected);save();render();toast(`已将${E.cityBy(selected).name}加入行程`);}
function toggleAudio(){s.muted=!s.muted;if(!s.muted){try{if(!audioCtx){audioCtx=new (window.AudioContext||window.webkitAudioContext)();const n=audioCtx.sampleRate*3,buffer=audioCtx.createBuffer(1,n,audioCtx.sampleRate),data=buffer.getChannelData(0);let last=0;for(let i=0;i<n;i++){last=(last+Math.random()*.02-.01)/1.01;data[i]=last;}const source=audioCtx.createBufferSource();source.buffer=buffer;source.loop=true;audioGain=audioCtx.createGain();audioGain.gain.value=.25;source.connect(audioGain).connect(audioCtx.destination);source.start();}audioCtx.resume();audioGain.gain.setTargetAtTime(.25,audioCtx.currentTime,.5);}catch{s.muted=true;toast('此浏览器暂不支持声音');}}else if(audioGain)audioGain.gain.setTargetAtTime(0,audioCtx.currentTime,.3);save();render();if(modalView==='settings')openModal('settings',false);}
function bell(){if(!audioCtx||s.muted)return;[520,780,1040].forEach((f,i)=>{const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=f;o.connect(g).connect(audioCtx.destination);g.gain.setValueAtTime(.035,audioCtx.currentTime+i*.12);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.7+i*.12);o.start(audioCtx.currentTime+i*.12);o.stop(audioCtx.currentTime+.8+i*.12);});}
function changeNight(){night=world?.night()||false;$('#night-mode').style.color=night?'#7287a1':'';if(modalView==='settings')openModal('settings',false);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){if(b.dataset.view==='map')closeModal();else openModal(b.dataset.view);return;}if(b.dataset.tab){tab=b.dataset.tab;$$('[data-tab]').forEach(el=>el.classList.toggle('active',el===b));render();return;}if(b.dataset.trade){const gid=b.dataset.trade,n=qty();act(()=>tab==='market'?E.buy(s,gid,n):E.sell(s,gid,n),`${tab==='market'?'购入':'售出'} ${n} 箱${E.goodBy(gid).name}`);bell();return;}if(b.dataset.supply){act(()=>E.supply(s,b.dataset.supply),'补给已装入行囊');return;}if(b.dataset.removeStop!==undefined){s.route.splice(+b.dataset.removeStop,1);save();render();return;}if(b.dataset.speed){s.speed=+b.dataset.speed;save();render();return;}if(b.dataset.upgrade){act(()=>E.upgrade(s,b.dataset.upgrade),'商队升级完成');return;}if(b.dataset.contract){const id=b.dataset.contract;act(()=>b.dataset.contractAction==='deliver'?E.deliverContract(s,id):E.acceptContract(s,id),b.dataset.contractAction==='deliver'?'委托完成，报酬已到账':'委托已记入商旅日志');return;}if(b.dataset.choice){const err=E.resolveEvent(s,b.dataset.choice);if(err){toast(err,'error');return;}closeModal();save();render();return;}if(b.dataset.selectCity){selectCity(b.dataset.selectCity);return;}
switch(b.id){case 'add-route':addRoute();break;case 'clear-route':s.route=[];save();render();break;case 'depart':act(()=>E.depart(s));bell();break;case 'qty-minus':$('#trade-qty').value=Math.max(1,qty()-1);break;case 'qty-plus':$('#trade-qty').value=Math.min(99,qty()+1);break;case 'resupply':act(()=>E.resupply(s),'水与口粮已补满');break;case 'rest':act(()=>E.rest(s),'休整完成，士气恢复');break;case 'rescue':act(()=>E.rescue(s),'应急补给已领取');break;case 'pause':s.paused=!s.paused;render();save();break;case 'help-btn':openModal('help');break;case 'settings-btn':openModal('settings');break;case 'modal-close':closeModal();break;case 'zoom-in':world?.zoom(1.15);break;case 'zoom-out':world?.zoom(1/1.15);break;case 'reset-camera':world?.reset();break;case 'night-mode':case 'toggle-night':changeNight();break;case 'audio':case 'toggle-audio':toggleAudio();break;case 'manual-save':save();toast('旅程已保存','good');break;case 'reset-game':openModal('reset');break;case 'cancel-reset':openModal('settings');break;case 'confirm-reset':s=E.freshState();selected='salt';tab='market';$$('[data-tab]').forEach(el=>el.classList.toggle('active',el.dataset.tab==='market'));save();closeModal();render();toast('新的商路，从曙光绿洲开始');break;case 'tutorial-route':if(!s.trip){selected='salt';s.route=s.location==='salt'?['dawn']:['salt'];}closeModal();save();render();break;}
});
$('#modal-backdrop').addEventListener('click',e=>{if(e.target===$('#modal-backdrop'))closeModal();});$('#trade-qty').addEventListener('change',()=>$('#trade-qty').value=qty());document.addEventListener('keydown',e=>{if(e.key==='Tab'&&modalView){const list=[...$('#modal').querySelectorAll('button:not(.hidden):not(:disabled),input')].filter(x=>x.offsetParent!==null);if(!list.length)return;if(e.shiftKey&&document.activeElement===list[0]){e.preventDefault();list.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===list.at(-1)){e.preventDefault();list[0].focus();}return;}if(e.target.matches('input,textarea'))return;if(e.key==='Escape'){closeModal();return;}if(modalView)return;if(e.code==='Space'){e.preventDefault();s.paused=!s.paused;save();render();}if(e.key.toLowerCase()==='m')openModal('caravan');if(e.key.toLowerCase()==='c')openModal('contracts');if(e.key.toLowerCase()==='j')openModal('journal');});
function loop(now){const dt=Math.min((now-lastFrame)/1000,.1);lastFrame=now;if(!document.hidden){const wasTrip=!!s.trip;const changed=E.tick(s,dt);if(changed){if(wasTrip&&!s.trip){E.checkAchievements(s).forEach(n=>toast('✦ 达成成就：'+n,'good'));toast(`已抵达${E.cityBy(s.location).name}，可以开始交易了`,'good');selected=s.route[0]||s.location;bell();}save();render();}if(s.trip){renderJourney();saveTimer+=dt;if(saveTimer>2){saveTimer=0;save();}}}requestAnimationFrame(loop);}render();requestAnimationFrame(loop);window.addEventListener('pagehide',save);if(s.event)openModal('event');
// Stable read-only snapshot for automated gameplay verification.
window.caravanSnapshot=()=>JSON.parse(JSON.stringify(s));
